<?php declare(strict_types=1); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar · Trajetória</title><link rel="stylesheet" href="/workspace/production.css"></head><body class="auth-body"><main class="auth-shell"><section class="auth-story"><img src="/workspace/logo-trajetoria.png" alt="Trajetória"><span class="eyebrow">GESTÃO DE CARREIRAS MUNICIPAIS</span><h1>Cada carreira,<br>um próximo passo.</h1><p>Planos, formação, avaliações e evolução funcional reunidos em um ambiente de acesso individual.</p><div class="auth-pill">Sua matrícula. Sua história. Minha Trajetória.</div></section><section class="auth-panel"><span class="eyebrow">ACESSO INDIVIDUAL</span><h2 id="auth-title">Bem-vindo ao Trajetória</h2><p id="auth-description">Entre com o e-mail da sua conta ou CPF e sua senha.</p><form id="login-form"><label>E-mail ou CPF<input name="login" autocomplete="username" required maxlength="190"></label><label>Senha<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button class="btn">Entrar na plataforma →</button></form><form id="password-form" hidden><label>Senha atual ou temporária<input name="current" type="password" autocomplete="current-password" required></label><label>Nova senha<input name="password" type="password" autocomplete="new-password" required minlength="14" maxlength="128"></label><label>Confirme a nova senha<input name="confirmation" type="password" autocomplete="new-password" required minlength="14"></label><p>Use pelo menos 14 caracteres, com maiúsculas, minúsculas e números.</p><button class="btn">Salvar minha senha</button></form><p id="auth-error" class="form-error" role="alert"></p><p class="auth-help">Sem acesso ou esqueceu a senha? Solicite a redefinição ao gestor responsável. O CPF sozinho não concede acesso.</p><small>Não há integração ativa com GOV.br nesta versão.</small></section></main><script>
let token='';const error=document.querySelector('#auth-error');function passwordScreen(){document.querySelector('#login-form').hidden=true;document.querySelector('#password-form').hidden=false;document.querySelector('#auth-title').textContent='Defina sua senha pessoal';document.querySelector('#auth-description').textContent='A senha temporária deve ser substituída antes do primeiro acesso.';}if(location.search.includes('alterar=1'))passwordScreen();async function freshToken(){
 const r=await fetch('/api/auth/context?t='+Date.now(),{method:'GET',cache:'no-store',credentials:'same-origin',headers:{'Accept':'application/json'}});
 let d;try{d=await r.json();}catch{throw Error('Não foi possível preparar o acesso. Recarregue a página e tente novamente.');}
 if(!r.ok||typeof d.csrf!=='string'||!/^[a-f0-9]{64}$/.test(d.csrf))throw Error(d.error||'Não foi possível preparar a sessão de acesso.');
 token=d.csrf;
}
async function send(path,b){
 await freshToken();
 const r=await fetch('/api/auth/'+path,{method:'POST',cache:'no-store',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':token,'Accept':'application/json'},body:JSON.stringify(b)});
 let d;try{d=await r.json();}catch{throw Error('O servidor não retornou uma resposta de acesso válida. Tente novamente.');}
 if(!r.ok)throw Error(d.error||'Não foi possível concluir o acesso.');
 if(d.csrf)token=d.csrf;return d;
}
document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;error.textContent='';try{const r=await send('login',Object.fromEntries(new FormData(e.target)));if(r.changePassword)passwordScreen();else location.href='/ambiente';}catch(e){error.textContent=e.message;}finally{btn.disabled=false;}};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));if(b.password!==b.confirmation)throw Error('As senhas não coincidem.');await send('password',b);location.href='/ambiente';}catch(e){error.textContent=e.message;}};
</script></body></html>
